(function(){"use strict";const LANGS=[["en","English"],["fr","Français"],["de","Deutsch"],["pt-PT","Português"],["ru","Русский"],["ja","日本語"],["zh-CN","简体中文"],];const SUPPORTED=new Set(LANGS.map((l)=>l[0]));const STORAGE_KEY="btt_docs_lang";const originals=new WeakMap();const changed=new Set();let dict={};let current="en";const norm=(s)=>s.replace(/\s+/g," ").trim();const phOriginals=new WeakMap();const phChanged=new Set();function cacheOriginals(){document.querySelectorAll("[data-i18n]").forEach((el)=>{if(!originals.has(el))originals.set(el,el.innerHTML);});document.querySelectorAll("[data-i18n-placeholder]").forEach((el)=>{if(!phOriginals.has(el))phOriginals.set(el,el.getAttribute("placeholder")||"");});}
function restoreAll(){changed.forEach((el)=>{const orig=originals.get(el);if(orig!=null)el.innerHTML=orig;});changed.clear();phChanged.forEach((el)=>{const orig=phOriginals.get(el);if(orig!=null)el.setAttribute("placeholder",orig);});phChanged.clear();}
function applyDict(){restoreAll();if(current==="en")return;document.querySelectorAll("[data-i18n]").forEach((el)=>{const orig=originals.get(el);if(orig==null)return;const translated=dict[norm(orig)];if(translated!=null&&translated!==""){el.innerHTML=translated;changed.add(el);}});document.querySelectorAll("[data-i18n-placeholder]").forEach((el)=>{const orig=phOriginals.get(el);if(orig==null)return;const translated=dict[norm(orig)];if(translated!=null&&translated!==""){el.setAttribute("placeholder",translated);phChanged.add(el);}});}
async function loadLocale(lang){if(lang==="en"){dict={};return;}
try{const res=await fetch(`/static/locales/${lang}.json`,{cache:"no-cache"});dict=res.ok?await res.json():{};}catch(e){console.warn("i18n: failed to load locale",lang,e);dict={};}}
async function setLanguage(lang){if(!SUPPORTED.has(lang))lang="en";current=lang;try{localStorage.setItem(STORAGE_KEY,lang);}catch(e){}
document.documentElement.setAttribute("lang",lang);await loadLocale(lang);applyDict();document.querySelectorAll(".lang-select").forEach(sel=>{if(sel.value!==lang)sel.value=lang;});document.dispatchEvent(new CustomEvent("btt-lang-changed",{detail:{lang}}));}
function pickInitialLanguage(){let saved=null;try{saved=localStorage.getItem(STORAGE_KEY);}catch(e){}
if(saved&&SUPPORTED.has(saved))return saved;const nav=(navigator.language||"").toLowerCase();if(nav.startsWith("zh"))return"zh-CN";if(nav.startsWith("ja"))return"ja";if(nav.startsWith("ru"))return"ru";if(nav.startsWith("pt"))return"pt-PT";if(nav.startsWith("fr"))return"fr";if(nav.startsWith("de"))return"de";return"en";}
function buildSwitcher(){const selects=document.querySelectorAll(".lang-select");if(!selects.length)return;selects.forEach(sel=>{sel.innerHTML="";LANGS.forEach(([code,label])=>{const opt=document.createElement("option");opt.value=code;opt.textContent=label;sel.appendChild(opt);});sel.addEventListener("change",()=>setLanguage(sel.value));});}
function init(){cacheOriginals();buildSwitcher();setLanguage(pickInitialLanguage());}
if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",init);}else{init();}
window.BTTi18n={setLanguage};})();